<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>

using namespace std;

#define inf (ll)1e15
#define ll long long
#define all(x) x.begin(), x.end()
#define x first
#define y second

const int N = 200010;

const int mod = (int)1e9 + 7;
const int MX = 1000010;

std::vector<ll> ones({0ll});

int ans = MX;

void bst(ll x, int vv){

	if(vv > ans)
		return;

	if(x == 0){
		ans = vv;
		return;
	}

	auto lb = lower_bound(all(ones), x);
	auto ub = upper_bound(all(ones), x);

	if(lb == ub) lb--;

	ll rem = x - *lb;
	int cost = lb - ones.begin();
	ll rem2 = *ub - x;

	// cout << x << " " << vv << endl;

	bst(x % *lb, vv + cost * (x / *lb));
	bst(rem2, vv + cost + 1);
}

int main(){

    cin.tie(0);
    cin.sync_with_stdio(0);

    #ifdef Cyborg101
        freopen("input.txt", "r", stdin);
        freopen("output.txt", "w", stdout);
    #endif

    ll n;
    cin >> n;

    for(int i = 1; i <= 16; ++i){
    	ones.push_back(ones.back() * 10 + 1);
    }

	bst(n, 0);

    cout << ans << endl;

  	return 0;
}
